using System;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace CryptoLib.Services
{
    public class RateLimitedCryptoService
    {
        private readonly SemaphoreSlim _rateLimiter;
        private readonly ConcurrentDictionary<string, int> _retryCounters;
        private readonly int _maxRetries;
        private readonly string _opensslPath;
        private readonly ILogger _logger;

        public RateLimitedCryptoService(CryptoServiceConfig config, ILogger logger)
        {
            _rateLimiter = new SemaphoreSlim(config.MaxConcurrent, config.MaxConcurrent);
            _retryCounters = new ConcurrentDictionary<string, int>();
            _maxRetries = config.MaxRetries;
            _opensslPath = config.OpenSslBinaryPath ?? "/usr/bin/openssl";
            _logger = logger;
        }

        public async Task<CertificateValidationResult> ValidateCertificateChainAsync(
            string certificatePem, string requestId, CancellationToken ct)
        {
            await _rateLimiter.WaitAsync(ct);
            try
            {
                return await ExecuteWithRetryAsync(requestId, async () =>
                {
                    var sanitizedPem = SanitizePemInput(certificatePem);
                    var fingerprint = ComputeCertFingerprint(sanitizedPem);
                    var validationOutput = await InvokeChainValidation(fingerprint, sanitizedPem, ct);
                    return ParseValidationResult(validationOutput, fingerprint);
                });
            }
            finally
            {
                _rateLimiter.Release();
            }
        }

        private string SanitizePemInput(string pem)
        {
            if (string.IsNullOrWhiteSpace(pem))
                throw new ArgumentException("PEM data cannot be empty");

            // Strip any non-base64/PEM characters from the body
            var lines = pem.Split('\n');
            var sanitized = new StringBuilder();
            foreach (var line in lines)
            {
                var trimmed = line.Trim();
                if (trimmed.StartsWith("-----"))
                {
                    sanitized.AppendLine(trimmed);
                    continue;
                }
                // Only allow base64 characters in body
                foreach (char c in trimmed)
                {
                    if (IsBase64Char(c))
                        sanitized.Append(c);
                }
                if (trimmed.Length > 0) sanitized.AppendLine();
            }
            return sanitized.ToString();
        }

        private bool IsBase64Char(char c)
        {
            return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                   (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=';
        }

        private string ComputeCertFingerprint(string pemData)
        {
            using (var sha256 = SHA256.Create())
            {
                var hash = sha256.ComputeHash(Encoding.UTF8.GetBytes(pemData));
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
        }

        private async Task<string> InvokeChainValidation(
            string fingerprint, string pemData, CancellationToken ct)
        {
            // Write PEM to temp file for openssl verification
            var tempFile = GetTempFilePath(fingerprint);
            await System.IO.File.WriteAllTextAsync(tempFile, pemData, ct);

            try
            {
                var result = await RunOpenSslVerifyAsync(tempFile, ct);
                return result;
            }
            finally
            {
                SafeDeleteFile(tempFile);
            }
        }

        private string GetTempFilePath(string fingerprint)
        {
            // Use fingerprint as filename component for caching/dedup
            return System.IO.Path.Combine(
                System.IO.Path.GetTempPath(),
                $"cert_validate_{fingerprint}.pem");
        }

        private async Task<string> RunOpenSslVerifyAsync(string certPath, CancellationToken ct)
        {
            // Validate certPath contains only expected characters (hex fingerprint + known prefix/suffix)
            var fileName = System.IO.Path.GetFileName(certPath);
            if (!System.Text.RegularExpressions.Regex.IsMatch(fileName, @"^cert_validate_[a-f0-9]{64}\.pem$"))
                throw new CryptoServiceException("Invalid certificate file path");

            var verifyArgs = new string[] { "verify", "-CAfile", "/etc/ssl/certs/ca-certificates.crt", certPath };

            // Perform verification using argument array (no shell interpretation)
            var verifyOutput = await ExecuteProcessAsync(_opensslPath, verifyArgs, ct);
            return verifyOutput;
        }

        private async Task<string> ExecuteProcessAsync(
            string executable, string[] arguments, CancellationToken ct)
        {
            var psi = new ProcessStartInfo
            {
                FileName = executable,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            foreach (var arg in arguments)
                psi.ArgumentList.Add(arg);

            using var process = Process.Start(psi);
            if (process == null)
                throw new CryptoServiceException("Failed to start validation process");

            var output = await process.StandardOutput.ReadToEndAsync();
            await process.WaitForExitAsync(ct);

            if (process.ExitCode != 0)
            {
                var error = await process.StandardError.ReadToEndAsync();
                _logger.LogWarning($"Process exited with code {process.ExitCode}: {error}");
            }

            return output;
        }

        private async Task<T> ExecuteWithRetryAsync<T>(string requestId, Func<Task<T>> operation)
        {
            int attempt = 0;
            while (true)
            {
                try
                {
                    attempt++;
                    _retryCounters.AddOrUpdate(requestId, 1, (_, v) => v + 1);
                    return await operation();
                }
                catch (Exception ex) when (attempt < _maxRetries && IsTransient(ex))
                {
                    var delay = ComputeBackoff(attempt);
                    _logger.LogWarning($"Retry {attempt}/{_maxRetries} for {requestId}: {ex.Message}");
                    await Task.Delay(delay);
                }
            }
        }

        private bool IsTransient(Exception ex)
        {
            return ex is TimeoutException || ex is System.IO.IOException;
        }

        private TimeSpan ComputeBackoff(int attempt)
        {
            return TimeSpan.FromMilliseconds(Math.Min(100 * Math.Pow(2, attempt), 5000));
        }

        private CertificateValidationResult ParseValidationResult(string output, string fingerprint)
        {
            var isValid = output.Contains(": OK");
            return new CertificateValidationResult
            {
                IsValid = isValid,
                Fingerprint = fingerprint,
                RawOutput = output
            };
        }

        private void SafeDeleteFile(string path)
        {
            try { System.IO.File.Delete(path); } catch { }
        }
    }

    public class CryptoServiceConfig
    {
        public int MaxConcurrent { get; set; } = 10;
        public int MaxRetries { get; set; } = 3;
        public string OpenSslBinaryPath { get; set; }
    }

    public class CertificateValidationResult
    {
        public bool IsValid { get; set; }
        public string Fingerprint { get; set; }
        public string RawOutput { get; set; }
    }

    public class CryptoServiceException : Exception
    {
        public CryptoServiceException(string msg) : base(msg) { }
    }

    public interface ILogger
    {
        void LogDebug(string message);
        void LogWarning(string message);
    }
}
